CREATE TABLE IF NOT EXISTS log_events (event_id VARCHAR(128) PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, occurred_at DATETIME(6) NOT NULL, service VARCHAR(128) NOT NULL, environment VARCHAR(64) NOT NULL, level VARCHAR(16) NOT NULL, message TEXT NOT NULL, error_type VARCHAR(256), stack_trace TEXT, labels JSON, fingerprint CHAR(64) NOT NULL, truncated BOOLEAN NOT NULL DEFAULT FALSE, received_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), KEY idx_events_fingerprint (tenant_id,fingerprint));
CREATE TABLE IF NOT EXISTS alert_groups (id CHAR(16) PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, fingerprint CHAR(64) NOT NULL, service VARCHAR(128) NOT NULL, environment VARCHAR(64) NOT NULL, state VARCHAR(32) NOT NULL, event_count INT NOT NULL DEFAULT 0, first_seen DATETIME(6) NOT NULL, last_seen DATETIME(6) NOT NULL, reopen_count INT NOT NULL DEFAULT 0, resolved_at DATETIME(6), UNIQUE KEY uq_alert_fingerprint (tenant_id,fingerprint), KEY idx_alert_state_time (state,last_seen));
CREATE TABLE IF NOT EXISTS notification_jobs (id VARCHAR(256) PRIMARY KEY, alert_id CHAR(16) NOT NULL, channel VARCHAR(64) NOT NULL, kind VARCHAR(32) NOT NULL, sequence INT NOT NULL, attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, UNIQUE KEY uq_notification (alert_id,channel,kind,sequence), KEY idx_notification_due (available_at));
CREATE TABLE IF NOT EXISTS alert_policies (id VARCHAR(64) PRIMARY KEY, service VARCHAR(128) NOT NULL DEFAULT '', environment VARCHAR(64) NOT NULL DEFAULT '', error_type VARCHAR(256) NOT NULL DEFAULT '', trigger_count INT NOT NULL DEFAULT 1, window_seconds INT NOT NULL DEFAULT 300, recovery_window_seconds INT NOT NULL DEFAULT 300, severity VARCHAR(32) NOT NULL DEFAULT 'error', channels JSON NOT NULL);
CREATE TABLE IF NOT EXISTS silences (id VARCHAR(64) PRIMARY KEY, alert_id CHAR(16) NOT NULL, starts_at DATETIME(6) NOT NULL, ends_at DATETIME(6) NOT NULL, KEY idx_silence_active (alert_id,starts_at,ends_at));
CREATE TABLE IF NOT EXISTS alert_transitions (id BIGINT AUTO_INCREMENT PRIMARY KEY, alert_id CHAR(16) NOT NULL, from_state VARCHAR(32), to_state VARCHAR(32) NOT NULL, reason VARCHAR(512) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS notification_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(256) NOT NULL, success BOOLEAN NOT NULL, external_id VARCHAR(256), error_message VARCHAR(1024), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS notification_dead_letters (id BIGINT AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(256) NOT NULL, reason VARCHAR(1024) NOT NULL, attempts INT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
